mapper.select:
SELECT e.EXPRESSION_ID, e.EXPRESSION_CODE, e.EXPRESSION_NAME, e.EXPRESSION_TYPE, CASE e.EXPRESSION_TYPE WHEN 'LOGICAL' THEN '逻辑表达式' WHEN 'ARITHMETIC' THEN '算术表达式' WHEN 'COMPARISON' THEN '比较表达式' WHEN 'FUNCTION' THEN '函数表达式' ELSE e.EXPRESSION_TYPE END AS EXPRESSION_TYPE_NAME, e.EXPRESSION_CATEGORY, CASE e.EXPRESSION_CATEGORY WHEN 'FINANCIAL_AUDIT' THEN '财务审计' WHEN 'RISK_CONTROL' THEN '风险控制' WHEN 'COMPLIANCE_CHECK' THEN '合规检查' WHEN 'DATA_VALIDATION' THEN '数据验证' ELSE e.EXPRESSION_CATEGORY END AS EXPRESSION_CATEGORY_NAME, e.OUTPUT_TYPE, e.DESCRIPTION, e.EXPRESSION_CONTENT, e.IS_ENABLED, CASE e.IS_ENABLED WHEN 'Y' THEN '启用' ELSE '禁用' END AS IS_ENABLED_NAME, e.IS_TEMPLATE, CASE e.IS_TEMPLATE WHEN 'Y' THEN '是' ELSE '否' END AS IS_TEMPLATE_NAME, e.COMPLEXITY_LEVEL, CASE e.COMPLEXITY_LEVEL WHEN 1 THEN '简单' WHEN 2 THEN '一般' WHEN 3 THEN '中等' WHEN 4 THEN '复杂' WHEN 5 THEN '很复杂' ELSE '未知' END AS COMPLEXITY_LEVEL_NAME, e.TAGS, e.SOURCE_DATA_CONFIG, e.TARGET_DATA_CONFIG, e.COMPARISON_RULES, e.EXECUTION_COUNT, e.SUCCESS_COUNT, CASE WHEN e.EXECUTION_COUNT > 0 THEN ROUND(e.SUCCESS_COUNT * 100.0 / e.EXECUTION_COUNT, 2) || '%' ELSE '0%' END AS SUCCESS_RATE, e.LAST_EXECUTION_TIME, e.LAST_EXECUTION_RESULT, CASE e.LAST_EXECUTION_RESULT WHEN 'SUCCESS' THEN '成功' WHEN 'FAILED' THEN '失败' ELSE '未执行' END AS LAST_EXECUTION_RESULT_NAME, e.CREATE_USER, e.CREATE_TIME, e.UPDATE_USER, e.UPDATE_TIME FROM TBL_EXPRESSION_MANAGEMENT e
AND e.EXPRESSION_NAME LIKE '%' || #{query.expressionName} || '%'
AND e.EXPRESSION_TYPE = #{query.expressionType}
AND e.EXPRESSION_CATEGORY = #{query.expressionCategory}
AND e.IS_ENABLED = #{query.isEnabled}
AND e.IS_TEMPLATE = #{query.isTemplate}
AND e.CREATE_USER LIKE '%' || #{query.createUser} || '%'
AND e.CREATE_TIME >= TO_DATE(#{query.startTime}, 'YYYY-MM-DD HH24:MI:SS')
AND e.CREATE_TIME <= TO_DATE(#{query.endTime}, 'YYYY-MM-DD HH24:MI:SS')
ORDER BY e.CREATE_TIME DESC
